package main
import("context";"errors";"log/slog";"net/http";"os";"os/signal";"syscall";"time";"github.com/LeonQin-ai/light-agent/control/internal/config";"github.com/LeonQin-ai/light-agent/control/internal/dispatcher";"github.com/LeonQin-ai/light-agent/control/internal/feishu";"github.com/LeonQin-ai/light-agent/control/internal/httpapi";"github.com/LeonQin-ai/light-agent/control/internal/store")
func main(){c:=config.Load();l:=slog.New(slog.NewJSONHandler(os.Stdout,nil));st,e:=store.Open(c.DBPath);if e!=nil{l.Error("open store","error",e);os.Exit(1)};defer st.Close();ctx,stop:=signal.NotifyContext(context.Background(),syscall.SIGINT,syscall.SIGTERM);defer stop();go dispatcher.New(st,l).Run(ctx);hook:=feishu.New(st,feishu.Config{Token:c.FeishuVerificationToken,EncryptKey:c.FeishuEncryptKey,Allowed:c.FeishuAllowedOpenIDs});srv:=httpapi.HTTPServer(c.ListenAddr,httpapi.New(st,hook));go func(){l.Info("listening","addr",c.ListenAddr);if e:=srv.ListenAndServe();e!=nil&&!errors.Is(e,http.ErrServerClosed){l.Error("http server","error",e);stop()}}();<-ctx.Done();sd,cancel:=context.WithTimeout(context.Background(),10*time.Second);defer cancel();if e:=srv.Shutdown(sd);e!=nil{l.Error("shutdown","error",e)}}
